import { useGoogleLogin } from '@react-oauth/google'
import React, { useContext, useEffect, useRef, useState } from 'react'
import { LoginStateContext } from '../../App'
import axios from 'axios'
import { serverURL } from '../../apiinfo'
import { useCookies } from 'react-cookie'
import { loginResInterface } from '../../interfaces/loginResInterface'
import { Navigate } from 'react-router-dom'
import "./LoginPageMain.css"

function LoginPageMain() {
    const setLoginState:any = useContext(LoginStateContext)
    const [authCode,setAuthCode] = useState<string>("")
    const [cookies,setCookie] = useCookies()
    const [redirectFlg,setRedirectFlg] = useState<Boolean>(false)
    useEffect(()=>{
        console.log(authCode)
        if (authCode){
            axios.post(`${serverURL}/user/auth`,{
                authCode:authCode as string,
                jwtToken:""
            }).then((res)=>{
                setLoginState(true)
                console.log(res.data.token)
                setCookie("jwt_token",res.data.token)
                setRedirectFlg(true)
            }).catch((error)=>console.log(error))
        }
    },[authCode])

    const login = useGoogleLogin({
        flow:"auth-code",
        onSuccess:(res)=>{
            setAuthCode(res.code)
        }
    })
  return (
    <div className='LoginPageMain'>
        <div className='loginSpace'>
            <div className='loginSpaceTop'>
                <span className='appTitle'>Regic</span>
            </div>
            <div className='loginSpaceBottom'>
                <button className='loginButton' onClick={login}>
                    <img src='https://www.svgrepo.com/show/475656/google-color.svg' className='loginSpaceButtonIcon' alt=''/>
                    <span className='loginSpaceButtonTitle'>Login with Google</span>
                </button>
            </div>
        </div>
        {redirectFlg?<Navigate replace to="/home"/>:<></>}
    </div>
  )
}

export default LoginPageMain