import React, { useEffect, useRef, useState } from 'react'
import './SoftwareKeyboard.css'
import { key_structure, symbol_key_structure } from './key-structure'

export type SoftwareKey = {
  type: 'char' | 'sys'
  input: string
  keytop: string
  keytopIcon?: string
  color?: string
  thinKey?: boolean
}

type SoftwareKeyboardProps = {
  onKeyPress?: (key: SoftwareKey) => void
  onJpSend?: (text: string) => void
}

const DEFAULT_KEY_COLOR = '#22A5A3'
const KEY_LAYOUT_DEFAULT: SoftwareKey[][] = key_structure
const KEY_LAYOUT_SYMBOL: SoftwareKey[][] = symbol_key_structure
const getKeyColor = (key: SoftwareKey) => key.color ?? DEFAULT_KEY_COLOR

const SoftwareKeyboard: React.FC<SoftwareKeyboardProps> = ({ onKeyPress, onJpSend }) => {
  const [isCtrlActive, setIsCtrlActive] = useState(false)
  const [isSymbolLayer, setIsSymbolLayer] = useState(false)
  const [jpText, setJpText] = useState('')
  const [isJpBoxVisible, setIsJpBoxVisible] = useState(false)
  const jpTextareaRef = useRef<HTMLTextAreaElement | null>(null)

  const handleSendJp = () => {
    if (!jpText.trim()) return
    if (onJpSend) {
      onJpSend(jpText)
    } else if (onKeyPress) {
      // onJpSend が渡されていない場合は、1文字ずつキーイベントとして送信
      for (const ch of jpText) {
        const key = { type: 'char' as const, input: ch, keytop: ch }
        onKeyPress(key)
      }
    }
    setJpText('')
  }

  useEffect(() => {
    if (!isJpBoxVisible) return
    const textarea = jpTextareaRef.current
    if (!textarea) return

    textarea.style.height = 'auto'
    textarea.style.height = `${textarea.scrollHeight}px`
  }, [jpText, isJpBoxVisible])

  const handleClick = (key: SoftwareKey) => {
    // 修飾キーの扱い
    if (key.type === 'sys') {
      if (key.input === 'jp') {
        setIsJpBoxVisible((prev) => !prev)
        if (onKeyPress) {
          onKeyPress(key)
        }
        return
      }

      // レイヤー切り替えキー
      if (key.input === '__LAYER__') {
        setIsSymbolLayer((prev) => !prev)
        return
      }

      if (key.input === '__CTRL__') {
        // Ctrl はトグル動作（押すたびに ON/OFF）
        setIsCtrlActive((prev) => !prev)
        return
      }

      // SHIFT / ALT は今のところ修飾状態だけを表現しないので送信しない
      if (key.input === '__SHIFT__' || key.input === '__ALT__') {
        return
      }

      // それ以外のシステムキー（矢印、ESC、Space、Enter など）はそのまま送る
      if (onKeyPress) {
        onKeyPress(key)
      }
      return
    }

    // 文字キーの扱い
    let sendKey: SoftwareKey = key

    if (isCtrlActive) {
      // Ctrl + アルファベットのときは制御文字に変換（例: Ctrl+C -> \x03）
      const ch = key.input.charAt(0)
      const upper = ch.toUpperCase()
      if (upper >= 'A' && upper <= 'Z') {
        const code = upper.charCodeAt(0) - 64 // A(65)->1, Z(90)->26
        const ctrlChar = String.fromCharCode(code)
        sendKey = { ...key, input: ctrlChar }
      }

      // 一度使ったら Ctrl は解除
      setIsCtrlActive(false)
    }

    if (onKeyPress) {
      onKeyPress(sendKey)
    }
  }

  return (
    <div className='software-keyboard'>
      {isJpBoxVisible && (
        <div className='software-keyboard-input-wrapper'>
          <textarea
            className='software-keyboard-textarea'
            ref={jpTextareaRef}
            value={jpText}
            onChange={(e) => setJpText(e.target.value)}
            placeholder='日本語入力用テキストボックス'
          />
          <button
            type='button'
            className='software-keyboard-send-button'
            onClick={handleSendJp}
          >
            <img
              src='icon/send-horizontal.svg'
              alt='送信'
              className='software-keyboard-send-icon'
            />
          </button>
        </div>
      )}
      {(isSymbolLayer ? KEY_LAYOUT_SYMBOL : KEY_LAYOUT_DEFAULT).map((row, rowIdx) => (
        <div key={`row-${rowIdx}`} className='keyboard-row'>
          {row.map((keyValue) => (
              <button
              key={`${keyValue.type}-${keyValue.input}-${rowIdx}`}
              className={`keyboard-key ${keyValue.type}-key${keyValue.keytopIcon ? ' has-icon' : ''}${keyValue.thinKey ? ' thin-key' : ''}${keyValue.input === '__CTRL__' && isCtrlActive ? ' modifier-active' : ''}`}
              style={{ borderColor: getKeyColor(keyValue) }}
              onClick={() => handleClick(keyValue)}
            >
              {keyValue.keytopIcon ? (
                <img
                  src={keyValue.keytopIcon}
                  alt={keyValue.keytop}
                  className='keytop-icon'
                />
              ) : (
                keyValue.keytop
              )}
            </button>
          ))}
        </div>
      ))}
    </div>
  )
}

export default SoftwareKeyboard
