import React, { useContext, useRef, useState } from 'react'
import "./HostMachineMain.css"
import { SocketContext } from '../../../App'
import { useCookies } from 'react-cookie'
import axios from 'axios'
import { serverURL } from '../../../apiinfo'

function HostMachineMain(props:{title:string,machineId:string,run_sys:string,isOnline:boolean}) {
    const socket:any = useContext(SocketContext)
    const [cookies,setCookies] = useCookies()
    const [runSys,setRunSys] = useState(props.run_sys)
    const contentRef = useRef<any>(null)
    const connection_request = ()=>{
        socket.emit("connection_request",{machineId:props.machineId,run_sys:runSys,jwtToken:cookies.jwt_token})
    }
    const restart_host = ()=>{
      socket.emit("restart_host",{machineId:props.machineId,token:cookies.jwt_token})
    }
    const update_run_sys = ()=>{
      axios.post(`${serverURL}/remotemachine/changerunsys`,{
        jwt_token:cookies.jwt_token as any,
        machineId:props.machineId,
        run_sys:runSys
      }).then((res)=>{}).catch((error)=>{
        alert("update error")
      })
    }
    const delete_machine = async()=>{
      axios.post(`${serverURL}/remotemachine/deletemachine`,{
           jwt_token:cookies.jwt_token as any,
           machineId:props.machineId
      }).then((res)=>{
        contentRef.current.remove()
      }).catch((error)=>{
        alert("delete error")
      })
    }
  return (
    <div className='HostMachineMain' ref={contentRef}>
        <img src='/icon/server_fill (7).svg' className='HostMachineMainIcon' alt=''/>
        <div>
          <span className='HostMachineMainTitle'>{props.title}</span>
          <div className='HostMachineMainButtons'>
              <input type='text' className='HostMachineMainButtonsInput' value={runSys} onChange={(e:any)=>setRunSys(e.target.value)} onBlur={update_run_sys}/>
             {props.isOnline?<button className='HostMachineButton connect' onClick={connection_request}>connect</button>:<button className='HostMachineButton offButton'>connect</button>}
             {props.isOnline?<button className='HostMachineButton restart' onClick={restart_host}>restart</button>:<button className='HostMachineButton offButton'>restart</button>}
             <button className='HostMachineDeleteButton' onClick={delete_machine}><img src="/icon/delete_2_fill.svg" alt='' className='HostMachineDeleteButtonIcon'/></button>
          </div>
        </div>
    </div>
  )
}

export default HostMachineMain