import axios from 'axios'
import React, { useContext, useEffect, useRef, useState } from 'react'
import { useCookies } from 'react-cookie'
import { serverURL } from '../../apiinfo'
import { machineListInterface, onlineRemoteMachineInterface, RemoteMachineInterface, RemoteMachineInterfaceMain } from '../../interfaces/remoteMachineInterface'
import MachineItem from '../machineItem/MachineItem'
import { SetFirstLogContext, SocketContext } from '../../App'
import { Navigate } from 'react-router-dom'
import "./HomePageMain.css"
import HostMachineMain from './HostMachine/HostMachineMain'
import { jwtDecode } from 'jwt-decode'

function HomePageMain() {
    const [cookies,setCookie] = useCookies()
    const [firstLoadRestFlg,setFirstLoadRestFlg] = useState<Boolean>(false)
    const [firstLoadSocketFlg,setFirstLoadSocketFlg] = useState<Boolean>(false)
    const [isOnline,setIsOnline] = useState<Boolean>(false)
    const [machineList,setMachineList] = useState<machineListInterface>()
    const [navigateContent,setNavigateContent] = useState<any>(<></>)
    const [machineSettingToken,setMachineSettingToken] = useState<string>("")
    const socket:any = useContext(SocketContext)
    const firstLog:any = useContext(SetFirstLogContext)
    const decoder = new TextDecoder("shift-jis")
    const isFirst = useRef<boolean>(true)
    const [userData,setUserData] = useState<{pic:string,name:string}>({pic:"",name:""})
    const copy_token = ()=>{
        navigator.clipboard.writeText(machineSettingToken).then(()=>{},(error:any)=>{})
    }
    useEffect(()=>{
        if (isFirst.current){
            isFirst.current = false
            socket.emit("first_handshake",{userType:"client",token:cookies.jwt_token})
            socket.on("socket-error",(data:string)=>{
                // alert(data)
            })
            socket.on("new_process_created",(data:any)=>{
                console.log(data.data)
                firstLog.setFirstLog(data.data)
                firstLog.setMachineId(data.machineId)
                firstLog.setMachineName(data.machineName)
                setNavigateContent(<Navigate replace to="/workspace"/>)
            })
        }
      },[])
    useEffect(()=>{
        const userData:any = jwtDecode(cookies.jwt_token)
        setUserData({pic:userData.picture,name:userData.name})
    },[])
    useEffect(()=>{
        if (!firstLoadRestFlg){
            setFirstLoadRestFlg(true)
            axios.post(`${serverURL}/remotemachine/generatemjwt`,{
                jwt_token:cookies.jwt_token
            }).then((res)=>{
                setMachineSettingToken(res.data.token)
                console.log(res.data.token)
            }).catch((error)=>{
                // alert(error)
            })
            axios.post(`${serverURL}/remotemachine/getmachine`,{
                jwt_token:cookies.jwt_token
            }).then((res)=>{
                const onlineUser = res.data.onlineRemoteMachine
                let offlineUser:any = []
                res.data.allRemoteMachine.forEach((i:any)=>{
                    const index = res.data.onlineRemoteMachine.findIndex((k:any)=>k.machineId === i.machineId)
                    if (index === -1){
                        offlineUser = [...offlineUser,i]
                    }
                })
                console.log(offlineUser)
                setMachineList({
                    offlineRemoteMachine:offlineUser,
                    onlineRemoteMachine:onlineUser,
                    allRemoteMachine:res.data.allRemoteMachine
                })
                const resData = res.data as machineListInterface
                if (resData.onlineRemoteMachine.length>0){
                    setIsOnline(true)
                }
                console.log(res.data)
            }).catch((error)=>{
                // alert(error)
            })
        }
    },[])

  return (
    <div>
        <div className='homePageMainContent'>
            <div className='homePageMainTop'>
                <span className='homePageMainTitle'>REGIC</span>
                <div className='homePageMainLeft'>
                    <div className='homePageMainIconSpace'>
                        <img src={userData.pic} className='homePageTopIcon' alt=''/>
                    </div>
                    <span className='homePageMainUserName'>{userData.name}</span>
                </div>
            </div>
            <div className='homePageMainBottom'>
                <div className='homePageSettingTokenSpace'>
                    <span className='homePageSettingTokenSpaceTitle'>Setting Token</span>
                    <div className='homePageSettingToken'>
                        <div className='homePageSettingTokenInputSpace'>
                            <input type='text' className='homePageSettingTokenInput' value={machineSettingToken}/>
                        </div>
                        <button className='homePageSettingTokenInputCopyButton' onClick={copy_token}>
                           <img src='/icon/copy_2_fill.svg' className='homePageSettingTokenInputCopyButtonIcon'/>
                        </button>
                    </div>
                    <div className='homePageSettingTokenSpaceLine'></div>
                </div>
                <div className='homePageSettingTokenSpace'>
                    <span className='homePageSettingTokenSpaceTitle'>Online Hosts</span>
                    <div className='homePageMachineContents'>
                        {isOnline?machineList?.onlineRemoteMachine.map((i:onlineRemoteMachineInterface)=>{
                            // return <MachineItem key={i.machineId} machineId={i.machineId} machineName={i.machineName} isOnline={true}/>
                            const machineInfo = machineList?.allRemoteMachine.find((k)=>k.machineId === i.machineId)
                            return <HostMachineMain title={i.machineName} run_sys={machineInfo?.run_sys as string} machineId={i.machineId} isOnline={true}/>
                        }):<span>None<br/></span>}
                    </div>
                    <div className='homePageSettingTokenSpaceLine'></div>
                </div>
                <div className='homePageSettingTokenSpace'>
                    <span className='homePageSettingTokenSpaceTitle'>Offline Hosts</span>
                    <div className='homePageMachineContents'>
                    {machineList?.offlineRemoteMachine.map((i:RemoteMachineInterfaceMain)=>{
                        return <HostMachineMain title={i.machineName} machineId={i.machineId} run_sys={i.run_sys} isOnline={false}/>
                    })} 
                </div>
                </div>
            </div>
        </div>
        {navigateContent}
    </div>
  )
}

export default HomePageMain