import React, { useCallback, useContext, useEffect, useRef, useState } from 'react'
import { SetFirstLogContext, SocketContext } from '../../App'
import "./WorkSpaceMain.css"
import { useCookies } from 'react-cookie'
import "./xterm.css"
import { FitAddon, init, Terminal } from 'ghostty-web';
import { Navigate } from 'react-router-dom'
import {jwtDecode} from "jwt-decode"
import { FullScreen, useFullScreenHandle } from "react-full-screen";
import SoftwareKeyboard, { SoftwareKey } from '../softwareKeyboard/SoftwareKeyboard'


// let isFirst:boolean = true

function sleep(ms:number) {
    return new Promise(resolve => setTimeout(resolve, ms));
}


function WorkSpaceMain() {
    const socket:any = useContext(SocketContext)
    const firstLog:any = useContext(SetFirstLogContext)
    const firstFlg = useRef(true)
    const [cookies,setCookie] = useCookies()
    const [moveElement,setMoveElement] = useState<any>(<></>)
    const mainUserId = useRef<string>("")
    const resizeFlg = useRef<boolean>(true)
    const handle = useFullScreenHandle();
    const [hideFullScreenButton,setHideFullScreenButton] = useState<string>("none")
    const [isMobileViewport,setIsMobileViewport] = useState<boolean>(false)
    const [isDisplaySoftwareKeyboard,setIsDisplaySoftwareKeyboard] = useState<boolean>(false)
    const [terminalInitError,setTerminalInitError] = useState<string>("")
    const updateViewportMode = () => {
        if (typeof window === 'undefined'){
            return
        }
        setIsMobileViewport(window.innerWidth <= 768)
        setIsDisplaySoftwareKeyboard(window.innerWidth <= 768)
    }
    useEffect(()=>{
        if (!firstFlg.current){
            return
        }
        firstFlg.current = false

        let isDisposed = false
        let term: Terminal | null = null
        let fitAdd: FitAddon | null = null

        document.title = firstLog.machineName
        const decodedToken:any = jwtDecode(cookies.jwt_token)
        mainUserId.current = decodedToken.userId

        const emitResize = ()=>{
            if (!term){
                return
            }
            socket.emit("resize_term",{
                token:cookies.jwt_token,
                size:[term.cols,term.rows],
                machineId:firstLog.machineId
            })
        }

        const processResultHandler = (result:any)=>{
            term?.write(result.data.data)
            console.log(result.data.data)
        }
        const disconnectRemoteMachineHandler = (_data:{machineId:string})=>{
            alert("remote machine is offline")
            setMoveElement(<Navigate replace to="/home"/>)
        }
        const socketErrorHandler = (data:string)=>{
            console.log(data)
        }

        const onWindowResize = async()=>{
            if (!resizeFlg.current || !fitAdd){
                return
            }
            resizeFlg.current = false
            await sleep(100)
            fitAdd.fit()
            emitResize()
            resizeFlg.current = true
        }

        const onDocumentKeydown = async(event:KeyboardEvent)=>{
            if (event.ctrlKey && event.key === "Shift"){
				setHideFullScreenButton((now:string)=>{
					if (now === "none"){
						return "block"
					}
					return "none"
				})
            }
			if (event.shiftKey && event.key === "Control"){
				const clipData = await navigator.clipboard.readText()
				socket.emit("run_command",{userId:mainUserId.current,command:clipData,machineId:firstLog.machineId})
			}
        }

        const setupTerminal = async()=>{
            try {
                await init()
                if (isDisposed){
                    return
                }

                term = new Terminal({
                    cursorBlink: true,
                    fontSize: 14,
                    theme: {
                        background: '#181a1f',
                        foreground: '#e5e7eb',
                        cursor: '#e5e7eb'
                    }
                })
                fitAdd = new FitAddon()
                term.loadAddon(fitAdd)
                term.open(document.getElementById("terminal") as HTMLElement)
                term.focus()
                term.write("\\r\\n[Regic] Terminal initialized. Waiting for remote output...\\r\\n")
                fitAdd.fit()
                fitAdd.observeResize()
                emitResize()

                const firstFit = async()=>{
                    await sleep(100)
                    if (isDisposed || !fitAdd){
                        return
                    }
                    fitAdd.fit()
                    emitResize()
                }
                firstFit()

                term.onData((data:string)=>{
                    socket.emit("run_command",{userId:mainUserId.current,command:data,machineId:firstLog.machineId})
                })

                socket.on("process_result",processResultHandler)
                socket.on("disconnect_remote_machine",disconnectRemoteMachineHandler)
                socket.on("socket-error",socketErrorHandler)

                window.addEventListener("resize",onWindowResize)
                document.addEventListener("keydown",onDocumentKeydown)
            } catch (error:any) {
                console.error("ghostty init failed", error)
                setTerminalInitError("Terminal initialization failed. Please reload the page.")
            }
        }

        setupTerminal()

        return ()=>{
            isDisposed = true
            socket.off("process_result",processResultHandler)
            socket.off("disconnect_remote_machine",disconnectRemoteMachineHandler)
            socket.off("socket-error",socketErrorHandler)
            window.removeEventListener("resize",onWindowResize)
            document.removeEventListener("keydown",onDocumentKeydown)
            fitAdd?.dispose()
            term?.dispose()
        }
    },[])

    useEffect(()=>{
        updateViewportMode()

        window.addEventListener("resize", updateViewportMode)
        return () => {
            window.removeEventListener("resize", updateViewportMode)
        }
    },[])


    const handleSoftwareKeyPress = useCallback((key:SoftwareKey)=>{
        if (!mainUserId.current){
            return
        }
        socket.emit("run_command",{userId:mainUserId.current,command:key.input,machineId:firstLog.machineId})
    },[socket,firstLog.machineId])
    
    const handleJpSend = useCallback((text:string)=>{
        if (!mainUserId.current){
            return
        }
        socket.emit("run_command",{
            userId:mainUserId.current,
            command:text,
            machineId:firstLog.machineId
        })
    },[socket,firstLog.machineId])
  return (
    <>
        <button onClick={handle.enter} style={{display:hideFullScreenButton}}>fullscreen</button>
        <FullScreen handle={handle}>
            <div className={`workspace-shell${isMobileViewport ? " is-mobile" : ""}`}>
                <div id='terminal' className='terminal-area' style={{height:isDisplaySoftwareKeyboard ? "68vh":"100vh"}}>
                </div>
                {terminalInitError ? <div style={{color:'#ff8b8b',background:'#1b1111',padding:'8px 12px',fontSize:'12px'}}>{terminalInitError}</div> : <></>}
                {isMobileViewport && (
                    <div className='software-keyboard-wrapper'>
                        <SoftwareKeyboard
                            onKeyPress={handleSoftwareKeyPress}
                            onJpSend={handleJpSend}
                        />
                    </div>
                )}
            </div>
            {moveElement}
        </FullScreen>
    </>
  )
}

export default WorkSpaceMain